/**
 * Matephis Sets Scene
 *
 * Draws a diagram of sets and maps from a JSON configuration: finite sets as
 * ovals with their elements, intervals as segments, rectangles and disks as
 * regions; maps as arrows between elements (or sample points); images,
 * preimages, collisions and properties computed by the model (model.js).
 *
 * Shared with the plot and physics engines (imported, not copied): expression
 * compiler, slider manager, palettes, MathJax bridge, label helpers.
 */
import { ExpressionCompiler } from '../../matephis-plot-src/parser/expression-parser.js';
import { createPalettes, cssLength, adaptColorForTheme } from '../../matephis-plot-src/core/config.js';
import { createSvgElement } from '../../matephis-plot-src/renderers/svg-factory.js';
import { renderMathJaxLabel, texReady } from '../../matephis-plot-src/renderers/mathjax-bridge.js';
import { SliderManager, paramScale } from '../../matephis-plot-src/ui/slider-manager.js';
import { WarningsMixin } from '../../matephis-plot-src/ui/warnings.js';
import { toTeX, estimateTextSize } from '../../matephis-physics-src/core/labels.js';
import { validateConfig } from './config.js';
import { SetsModel } from './model.js';
import { computeLayout, elementOrder, setLabelText } from './layout.js';
import { parseSelector } from './selectors.js';
import { Controls } from '../ui/controls.js';
import { Interaction } from '../ui/interaction.js';
import { drawSets, drawElements, drawHeader } from '../render/sets.js';
import { drawMapArrows, drawRoutedMaps, drawProbes, renderReadouts, compareReadout } from '../render/arrows.js';
import { Orbits } from '../render/orbits.js';
import { SyncGroup } from './sync.js';
import { Table } from '../render/table.js';
import { Product } from '../render/product.js';
import { drawLayer, renderProperties, drawPropertyMarks } from '../render/highlights.js';
import { LinkedPlot } from '../render/linked-plot.js';
import { lazyEnabled, flushPending, placeBlock, placeholder, slidersHeight } from '../../matephis-plot-src/core/lazy-init.js';

let uidCounter = 0;

/** Beside a plot: the narrowest each may be before they go one under the other, and the gap. */
const SIDE_MIN = 280;
const SIDE_GAP = 16;

/** Plain colour names, mapped to the site's palette. */
const COLOR_NAMES = {
    green: 'summer7', blue: 'summer3', lightblue: 'summer4', orange: 'summer6', yellow: 'summer5',
    red: 'red1', navy: 'summer2', purple: 'default5', gray: 'black3', grey: 'black3', black: 'black1',
};

/** Default colours of the computed layers. */
export const ROLE_COLORS = { image: 'green', preimage: 'blue', collisions: 'red', probe: 'orange', highlight: 'orange' };

/** A label is math unless it already mixes text and "$...$". */
export function mathLabel(str) {
    const s = String(str);
    return s.includes('$') ? s : `$${s}$`;
}

export class MatephisSets {
    /**
     * @param {HTMLElement} container
     * @param {string|object} source - JSON configuration
     * @param {object} [options]
     * @param {boolean} [options.observeResize=true]
     */
    constructor(container, source, options = {}) {
        this.container = container;
        this.config = typeof source === 'string' ? JSON.parse(source) : source;
        this.options = options;
        this.container.innerHTML = '';
        this.container.setAttribute('data-processed', 'true');
        this.uid = `mps${++uidCounter}`;
        this.params = {};
        this._initWarnings('Sets');
        this._listeners = [];
        const cfg = this.config;

        this.wrapper = document.createElement('div');
        this.wrapper.className = 'matephis-plot-container matephis-sets-container';
        if (cfg.border) this.wrapper.classList.add('bordered');
        this.wrapper.matephisSets = this;
        this.container.appendChild(this.wrapper);
        this._applyLayout();

        validateConfig(cfg).forEach(w => this._addWarning(w));
        // A dynagraph: parallel lines one under the other, same scale, ticks
        const dg = cfg.dynagraph;
        this.dynagraph = dg ? {
            ticks: typeof dg === 'object' && dg.ticks !== undefined ? dg.ticks : true,
            arrows: typeof dg === 'object' && dg.arrows !== undefined ? dg.arrows : 9,
        } : null;
        this.orient = this.dynagraph || cfg.layout === 'column' ? 'column' : 'row';

        const paramNames = Object.keys(cfg.params || {});
        this.compiler = new ExpressionCompiler({
            getParams: () => this.params, getPoints: () => ({}), paramNames,
        });
        SliderManager.initValues(cfg.params || {}, this.params, (v, ctx) => this._eval(v, ctx));
        this.model = new SetsModel(cfg, {
            evaluate: (v) => this._num(v, 'value'),
            compile: (src, vars) => this.compiler.fn(src, vars),
            warn: (m) => this._addWarning(m),
            isExpression: (src) => {
                try {
                    const v = this.compiler.eval(src);
                    return typeof v === 'number' && isFinite(v);
                } catch (e) {
                    return false;
                }
            },
        });

        this.palettes = createPalettes(this._isDark());
        this._listen(window, 'matephis-theme-change', () => {
            this.palettes = createPalettes(this._isDark());
            this.draw();
        });

        // A plot of the maps' graphs beside (or under) the diagram; it colours its maps first
        if (cfg.plot && typeof cfg.plot === 'object') {
            this.plotPosition = cfg.plot.position === 'below' ? 'below' : 'right';
            this.plotHost = document.createElement('div');
            this.plotHost.className = `matephis-sets-plot is-${this.plotPosition}`;
            this.linked = new LinkedPlot(this, this.plotHost);
        }

        // The IN/OUT table: its inputs become arrow samples, so it exists before the first draw
        if (cfg.table !== undefined) this.table = new Table(this, cfg.table);
        // A × B as a grid of pairs
        if (cfg.layout === 'product') {
            this.product = new Product(this, cfg.product);
            if (!this.product.ok) this.product = null;
        }
        this._initLayers();
        this._initSVG();
        if (this.table) {
            if (this.table.position === 'right' && !this.split) {
                const row = document.createElement('div');
                row.className = 'matephis-sets-split is-right';
                this.plotStage.before(row);
                row.appendChild(this.plotStage);
                row.appendChild(this.table.el);
            } else {
                (this.split || this.plotStage).after(this.table.el);
            }
        }

        this.propsEl = document.createElement('div');
        this.propsEl.className = 'matephis-sets-properties';
        this.wrapper.appendChild(this.propsEl);

        if (cfg.caption) {
            const cap = document.createElement('div');
            cap.className = 'matephis-plot-caption';
            cap.textContent = cfg.caption;
            this.wrapper.appendChild(cap);
        }

        if (Array.isArray(cfg.controls) && cfg.controls.length) {
            this.controls = new Controls(this, cfg.controls);
            this.wrapper.appendChild(this.controls.el);
        }
        // Orbits, step by step: their buttons go with the other buttons
        if (cfg.iterate !== undefined) {
            this.orbits = new Orbits(this, cfg.iterate);
            if (this.orbits.items.length) {
                if (this.controls) [...this.orbits.el.children].forEach(b => this.controls.el.appendChild(b));
                else this.wrapper.appendChild(this.orbits.el);
            }
        }
        if (cfg.params && cfg.showSliders !== false) {
            this.sliders = new SliderManager(this);
            this.sliders.init();
        }
        if (this.linked) {
            this.linked.mount();
            this.onFocus = (key) => this.linked.focusRow(key);
        }
        // Blocks with the same "sync" share params, hover and orbit steps
        if (typeof cfg.sync === 'string' && cfg.sync) this.syncGroup = SyncGroup.join(cfg.sync, this);

        this.interaction = new Interaction(this);
        this.draw();
        if (options.observeResize !== false) this._initResizeObserver();
    }

    /**
     * Scans the document for ```sets code blocks and .matephis-sets divs.
     * @param {object} [opts]
     * @param {boolean} [opts.lazy=false] - placeholders now, each block built when it comes
     *   near the screen (plot engine's lazy-init.js); blocks with the same "sync" are built
     *   together. Without it every block is built now.
     */
    static init(root = document, opts = {}) {
        const lazy = !!opts.lazy && lazyEnabled();
        if (!lazy) flushPending(root);
        const place = (container, source, label) => placeBlock(container, source, {
            lazy,
            build: (el, src, width) => new MatephisSets(el, src, width > 0 ? { width } : {}),
            placeholder: (cfg) => MatephisSets.placeholder(cfg),
            // Labels are math by default (mathLabel)
            needsMath: () => true,
            group: (cfg) => (typeof cfg.sync === 'string' && cfg.sync ? `sets:${cfg.sync}` : null),
            fail: (el, e) => {
                console.error(label, e);
                const div = document.createElement('div');
                div.className = 'matephis-plot-error';
                div.textContent = `Errore nel diagramma: ${e.message}`;
                el.appendChild(div);
            },
        });
        root.querySelectorAll('.matephis-sets').forEach(container => {
            if (container.getAttribute('data-processed')) return;
            const source = container.textContent;
            container.setAttribute('data-processed', 'true');
            container.innerHTML = '';
            place(container, source, 'Sets Error');
        });
        root.querySelectorAll('code.language-sets').forEach(code => {
            const target = code.closest('div.language-sets') || code.closest('pre') || code.parentElement;
            if (target.getAttribute('data-processed')) return;
            target.setAttribute('data-processed', 'true');
            const container = document.createElement('div');
            container.className = 'matephis-sets';
            container.setAttribute('data-processed', 'true');
            target.parentNode.insertBefore(container, target);
            target.style.display = 'none';
            place(container, code.textContent, 'Code Block Sets Error');
        });
    }

    /** A placeholder of about the size of a diagram, until it is built (the height of a diagram depends on its layout: a typical one). */
    static placeholder(cfg) {
        const plot = cfg.plot && typeof cfg.plot === 'object';
        return placeholder({
            className: `matephis-plot-container matephis-sets-container${cfg.border ? ' bordered' : ''}`,
            layout: (box) => MatephisSets.prototype._applyLayout.call({ config: { ...cfg }, wrapper: box }),
            // Calibrated on the site's pages (a typical diagram, its plot under it on a phone)
            height: 300,
            extra: slidersHeight(cfg) + (cfg.caption ? 24 : 0) + (plot ? 420 : 0)
                + (Array.isArray(cfg.probes) ? 27 * cfg.probes.length : 0) + (Array.isArray(cfg.controls) ? 40 : 0),
        });
    }

    /** Renders one diagram into an element (Obsidian, playground). Call .destroy() on unload. */
    static render(el, source, options = {}) {
        return new MatephisSets(el, source, options);
    }

    // =========================================================================
    // SETUP
    // =========================================================================

    _listen(target, type, fn, opts) {
        target.addEventListener(type, fn, opts);
        this._listeners.push([target, type, fn, opts]);
    }

    _applyLayout() {
        const cfg = this.config;
        const w = this.wrapper;
        if (cfg.fullWidth || (cfg.plot && cfg.plot.position !== 'below' && !cfg.cssWidth)) cfg.cssWidth = '100%';
        if (cfg.cssWidth) {
            w.style.maxWidth = cssLength(cfg.cssWidth);
            w.style.width = '100%';
        }
        if (cfg.align === 'center') w.classList.add('align-center');
        else if (cfg.align === 'left') w.classList.add('align-left');
        if (cfg.marginBottom !== undefined) w.style.marginBottom = cssLength(cfg.marginBottom);
        if (cfg.marginLeft !== undefined) w.style.marginLeft = cssLength(cfg.marginLeft);
        if (cfg.marginRight !== undefined) w.style.marginRight = cssLength(cfg.marginRight);
    }

    /** Width of the diagram out of the width there is: half of it when the plot is beside it. */
    _setsWidth(total) {
        if (this.plotPosition === 'right') {
            const half = Math.floor((total - SIDE_GAP) / 2);
            // Beside the plot only when the diagram still has room there; else under it
            const side = total >= 2 * SIDE_MIN && this._roomyAt(half);
            this._wantPlot = side ? 'right' : 'below';
            this._placePlot(this._wantPlot);
            if (side) return half;
        }
        return total;
    }

    /** Would the diagram be readable at width w? Lines of a column at least ~140 px (180 on a dynagraph), slots of a row ~110 px. */
    _roomyAt(w) {
        const n = Math.max(1, this.model.sets.length);
        if (this.orient !== 'column') return (w - 32) / n >= 110;
        const headerW = Math.max(20, ...this.model.sets.map(set => this.measure(setLabelText(this.model, set)).w)) + 34;
        // Dynagraphs need room for their ticks and numbers
        return w - 32 - headerW - 8 >= (this.dynagraph ? 180 : 140);
    }

    /** The plot beside the diagram or under it (on narrow pages, or when the diagram needs the width). */
    _placePlot(where) {
        if (!this.split || this._plotAt === where) return;
        this._plotAt = where;
        this.split.classList.toggle('is-right', where === 'right');
        this.split.classList.toggle('is-below', where === 'below');
        this.plotHost.classList.toggle('is-right', where === 'right');
        this.plotHost.classList.toggle('is-below', where === 'below');
    }

    _initSVG() {
        const cfg = this.config;
        const right = this.plotPosition === 'right';
        const observe = this.options.observeResize !== false;
        // The box's width on the page, read before the first draw (or measured by lazy-init.js)
        const cw = (cfg.fullWidth || right || observe) ? (this.options.width > 0 ? this.options.width : this.wrapper.clientWidth) : 0;
        let targetWidth = cfg.width || 600;
        if (cfg.fullWidth || right) {
            targetWidth = this._setsWidth(cw > 50 ? cw : Math.min(window.innerWidth || 600, 600));
            if (cfg.width) targetWidth = Math.min(targetWidth, cfg.width);
        }
        // Already the width the ResizeObserver would set (same rule as there and in
        // resize()): the first draw is the right one
        if (observe && cw > 10) {
            let w = this._setsWidth(Math.round(cw));
            if (w > 10 && Math.abs(w - Math.max(160, targetWidth)) > 2) {
                if ((!cfg.fullWidth || right) && cfg.width && w > cfg.width) w = cfg.width;
                targetWidth = w;
            }
        }
        this.width = Math.max(160, targetWidth);
        this.height = 200;
        this.plotStage = document.createElement('div');
        this.plotStage.className = 'matephis-plot-stage';
        if (this.plotHost) {
            // The diagram and the plot side by side (they wrap on narrow screens), or one under the other
            this.split = document.createElement('div');
            this.split.className = `matephis-sets-split is-${this.plotPosition}`;
            this.split.appendChild(this.plotStage);
            this.split.appendChild(this.plotHost);
            this.wrapper.appendChild(this.split);
            if (this._wantPlot) this._placePlot(this._wantPlot);
        } else {
            this.wrapper.appendChild(this.plotStage);
        }
        this.svg = createSvgElement('svg', {
            width: this.width, height: this.height, viewBox: `0 0 ${this.width} ${this.height}`,
            class: 'matephis-plot-svg matephis-sets-svg', role: 'img',
            'aria-label': cfg.ariaLabel || cfg.title || 'Diagramma di insiemi',
        });
        this.plotStage.appendChild(this.svg);
        const g = (cls) => {
            const el = createSvgElement('g', { class: cls });
            this.svg.appendChild(el);
            return el;
        };
        this.groups = {
            under: g('mps-under'), sets: g('mps-sets'), arrows: g('mps-arrows'), over: g('mps-over'),
            elements: g('mps-elements'), header: g('mps-header'), labels: g('mps-labels'), probe: g('mps-probe'),
        };
    }

    /**
     * Layers that can be drawn over the sets: the "show" list (always on),
     * highlights (on unless "hidden"), and selectors that only reveal buttons
     * name (off until pressed). Map arrows are layers too ("arrows(f)").
     */
    _initLayers() {
        const cfg = this.config;
        const layers = [];
        const seen = new Set();
        const add = (layer) => {
            if (seen.has(layer.key)) {
                const old = layers.find(l => l.key === layer.key);
                if (layer.always) old.always = true;
                return;
            }
            seen.add(layer.key);
            layers.push(layer);
        };
        // The arrows of each map, element by element. A composition is drawn
        // as one curve; its element arrows only with "arrows": true or a button
        this.model.maps.forEach(m => {
            // f^n ("iterate") has no curve of its own: its arrows are shown as a map's
            const always = m.kind === 'compose' && !m.iterate ? m.def.arrows === true : m.def.hidden !== true;
            add({ key: `arrows(${m.id})`, map: m, arrows: true, always });
        });
        const fromSelector = (str, always, where, extra = {}) => {
            const sel = parseSelector(str);
            if (!sel) return false;
            if (sel.unknown) {
                this._addWarning(`${where}: unknown operation in '${str}' (use image, preimage, domain, fixed, collisions, properties or arrows)`);
                return true;
            }
            if (!this.model.mapById.has(sel.map)) {
                this._addWarning(`${where}: no map '${sel.map}' in '${str}'`);
                return true;
            }
            // "arrows(f)" names the map's own layer
            if (sel.op === 'arrows') {
                if (always) layers.find(l => l.key === `arrows(${sel.map})`).always = true;
                return true;
            }
            add({ key: extra.id !== undefined ? String(extra.id) : sel.key, sel, always, ...extra });
            return true;
        };
        (Array.isArray(cfg.show) ? cfg.show : cfg.show !== undefined ? [cfg.show] : []).forEach((s, i) => {
            if (!fromSelector(String(s), true, `show[${i}]`)) this._addWarning(`show[${i}]: '${s}' is not a selector like "image(f)"`);
        });
        (Array.isArray(cfg.highlights) ? cfg.highlights : []).forEach((h, i) => {
            if (!h || typeof h !== 'object') return;
            const always = h.hidden !== true;
            if (h.of !== undefined) {
                if (!fromSelector(String(h.of), always, `highlights[${i}]`, { id: h.id, def: h })) {
                    this._addWarning(`highlights[${i}]: "of" must be a selector like "preimage(f, b_1)"`);
                }
                return;
            }
            const set = this.model.setById.get(String(h.set));
            if (!set) {
                this._addWarning(`highlights[${i}]: needs "of", or "set" with "elements" or "interval"`);
                return;
            }
            add({ key: h.id !== undefined ? String(h.id) : `highlight${i + 1}`, set, def: h, always });
        });
        Controls.targetsOf(cfg.controls).forEach(t => {
            if (!t.includes('*') && parseSelector(t)) fromSelector(t, false, 'controls');
        });
        this.layers = layers;
    }

    /** Is a layer visible now (always on, or revealed by a button)? */
    isVisible(layer) {
        return layer.always || (this.controls ? this.controls.isRevealed(layer.key) : false);
    }

    _initResizeObserver() {
        if (!window.ResizeObserver) return;
        // Resize on the next frame, not inside the observer callback: the redraw changes
        // the layout, which would raise "ResizeObserver loop completed with undelivered
        // notifications"; several reports in a frame make one redraw
        this._resizeFrame = 0;
        this.resizeObserver = new ResizeObserver(entries => {
            const newW = Math.round(entries[entries.length - 1].contentRect.width);
            if (this._resizeFrame) cancelAnimationFrame(this._resizeFrame);
            this._resizeFrame = requestAnimationFrame(() => {
                this._resizeFrame = 0;
                if (this._destroyed) return;
                const w = this._setsWidth(newW);
                if (w > 10 && Math.abs(w - this.width) > 2) this.resize(w);
            });
        });
        this.resizeObserver.observe(this.wrapper);
    }

    /** Re-lays out at a new width (text keeps its pixel size). */
    resize(w) {
        if ((!this.config.fullWidth || this.plotPosition === 'right') && this.config.width && w > this.config.width) w = this.config.width;
        this.width = Math.max(160, w);
        this.draw();
    }

    // =========================================================================
    // EXPRESSIONS, COLOURS, THEME
    // =========================================================================

    _eval(val, context = 'value') {
        if (typeof val === 'number') return val;
        if (typeof val === 'boolean') return Number(val);
        try {
            return this.compiler.eval(val);
        } catch (e) {
            this._addWarning(`${context}: ${e.message}`);
            return NaN;
        }
    }

    _num(val, context) {
        const r = this._eval(val, context);
        return typeof r === 'number' ? r : NaN;
    }

    /** Does a string (a selector argument) name one of the params? */
    mentionsParam(str) {
        const names = Object.keys(this.config.params || {});
        return names.some(n => new RegExp(`(^|[^A-Za-z0-9_])${n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}($|[^A-Za-z0-9_])`).test(String(str)));
    }

    setParam(key, value, redraw = true) {
        if (this.sliders && this.sliders.paramUIs[key]) this.sliders.setValue(key, value, false);
        else {
            const def = this.config.params && this.config.params[key];
            this.params[key] = value * paramScale(def);
        }
        if (redraw) this.requestDraw();
    }

    _isDark() {
        if (this.config.theme === 'dark') return true;
        if (typeof MatephisSets.isDarkHook === 'function') return !!MatephisSets.isDarkHook();
        return typeof document !== 'undefined' && document.documentElement.getAttribute('data-theme') === 'dark';
    }

    /** Colour from a name ("green"), a palette entry ("summer3"), a CSS colour, or a role default. */
    color(explicit, role = null) {
        const name = explicit || (role && ROLE_COLORS[role]) || null;
        const dark = this._isDark();
        if (!name) return dark ? '#e2e8f0' : '#1f1f1f';
        const key = COLOR_NAMES[name] || name;
        const named = this.palettes[key];
        if (typeof named === 'string') return adaptColorForTheme(named, dark);
        if (Array.isArray(named)) return adaptColorForTheme(named[0], dark);
        return adaptColorForTheme(name, dark);
    }

    get ink() {
        return this._isDark() ? '#e2e8f0' : '#1f1f1f';
    }

    // =========================================================================
    // SVG PRIMITIVES
    // =========================================================================

    svgEl(tag, attrs, parent) {
        const el = createSvgElement(tag, attrs);
        if (parent) parent.appendChild(el);
        return el;
    }

    get fontSize() {
        return this.config.fontSize || 16;
    }

    /** Size of a label, as it will be drawn. */
    measure(label, size) {
        return estimateTextSize(mathLabel(label), size || this.fontSize);
    }

    /**
     * Text with a halo; labels are math by default ("a_1" is a₁), "$...$"
     * mixes text and math. MathJax when the page loads it, plain text otherwise.
     */
    text(x, y, raw, { anchor = 'middle', baseline = 'middle', color, size, weight = 'normal', parent, math = true } = {}) {
        const str = math ? mathLabel(raw) : String(raw);
        const fontSize = size || this.fontSize;
        const fill = color || this.ink;
        const dark = this._isDark();
        const plain = () => {
            const t = this.svgEl('text', {
                x, y, class: 'matephis-plot-text', 'text-anchor': anchor, 'dominant-baseline': baseline,
                fill, 'font-size': `${fontSize}px`, 'font-weight': weight,
            }, parent);
            t.textContent = str.replace(/\$/g, '');
            t.style.paintOrder = 'stroke';
            t.style.stroke = dark ? '#181818' : '#fff';
            t.style.strokeWidth = '2.5px';
            return t;
        };
        if (str.includes('$') && texReady(this)) {
            const halo = this.config.labelHalo !== false ? { color: dark ? '#181818' : '#fff' } : null;
            return renderMathJaxLabel(toTeX(str), x, y, fontSize, fill, anchor, baseline, parent, plain, { halo, owner: this });
        }
        return plain();
    }

    // =========================================================================
    // DRAWING
    // =========================================================================

    requestDraw() {
        if (this._drawQueued) return;
        this._drawQueued = true;
        const run = () => {
            if (!this._drawQueued) return;
            this._drawQueued = false;
            if (!this._destroyed) this.draw();
        };
        requestAnimationFrame(run);
        // A page in the background gets no animation frames (scripted tests, hidden
        // panes): a timer draws anyway, so params set from JS show up
        setTimeout(run, 120);
    }

    /** Draws everything; warnings raised while drawing replace the previous draw's (ui/warnings.js). */
    draw() {
        return this._drawingWarnings(() => this._drawNow());
    }

    _drawNow() {
        if (this._destroyed) return;
        const cfg = this.config;
        this.model.refresh();
        // Room under the sets: curves of compositions, labels of collisions
        const footer = this.layers.some(l => (l.arrows && this._routed(l.map) && this._curveShown(l))
            || (l.sel && l.sel.op === 'collisions' && this.isVisible(l)));
        this.layout = this.product ? this.product.layout() : computeLayout(this.model, {
            width: this.width, orient: this.orient, fontSize: this.fontSize,
            measure: (s) => this.measure(s), order: elementOrder(this.model, { reorder: cfg.reorder !== false, orient: this.orient }),
            footer, spacing: typeof cfg.spacing === 'number' ? cfg.spacing : undefined, selfSets: this._selfSets(),
            height: typeof cfg.height === 'number' ? cfg.height : undefined,
        });
        this.height = Math.ceil(this.layout.height);
        this.svg.setAttribute('width', this.width);
        this.svg.setAttribute('height', this.height);
        this.svg.setAttribute('viewBox', `0 0 ${this.width} ${this.height}`);
        // Beside a plot the stage is a flex item: it takes exactly the diagram's width
        if (this.split) this.plotStage.style.width = `${this.width}px`;
        Object.values(this.groups).forEach(g => { g.textContent = ''; });
        this.interaction.reset();

        // Arrow colours of collisions are decided before the arrows are drawn
        this.arrowStyle = new Map();
        this.layers.filter(l => l.sel && l.sel.op === 'collisions' && this.isVisible(l)).forEach(l => {
            const map = this.model.mapById.get(l.sel.map);
            const color = this.color(l.def && l.def.color, 'collisions');
            this.model.collisions(map).forEach(c => c.sources.forEach(s => {
                this.arrowStyle.set(`${map.id}|${s}|${typeof c.target === 'string' ? c.target : JSON.stringify(c.target)}`, color);
            }));
        });

        const arrowLayers = this.layers.filter(l => l.arrows);
        if (this.product) {
            this.product.draw();
        } else {
            drawSets(this);
            arrowLayers.filter(l => !this._routed(l.map) && this.isVisible(l)).forEach(l => drawMapArrows(this, l.map));
            drawRoutedMaps(this, arrowLayers.filter(l => this._routed(l.map) && this._curveShown(l)).map(l => ({ map: l.map, arrows: this.isVisible(l) })));
            drawElements(this);
            // The arrow A -f-> B between the names: for the maps drawn (a hidden map
            // is not named until a button shows it), or followed by a probe
            const probed = new Set((Array.isArray(cfg.probe) ? cfg.probe : cfg.probe ? [cfg.probe] : []).map(p => p && String(p.map)));
            drawHeader(this, arrowLayers.filter(l => !this._routed(l.map) && (this.isVisible(l) || probed.has(l.map.id) || l.map.from === l.map.to)).map(l => l.map));
        }
        const props = [];
        const layerReadouts = [];
        this.layers.forEach(l => {
            if (l.arrows || !this.isVisible(l)) return;
            if (l.sel && l.sel.op === 'properties') {
                props.push(l);
                if (!this.product) drawPropertyMarks(this, this.model.mapById.get(l.sel.map));
            } else if (this.product) {
                drawLayer(this, l, { product: this.product });
            } else {
                const r = drawLayer(this, l);
                if (r) layerReadouts.push(r);
            }
        });
        this.probeValues = [];
        const readouts = [...drawProbes(this)];
        const cmp = compareReadout(this);
        if (cmp) readouts.push(cmp);
        readouts.push(...(this.orbits ? this.orbits.draw() : []), ...layerReadouts);
        if (readouts.length || this.readoutEl) renderReadouts(this, readouts);
        if (this.table) this.table.draw();
        renderProperties(this, props);
        if (this.controls) this.controls.update();
        if (this.linked) this.linked.sync();
        this.interaction.bind();
        if (this.syncGroup) this.syncGroup.publish(this);
    }

    /** Ids of sets with a map into themselves (drawn as arcs before the set) or an orbit. */
    _selfSets() {
        const ids = new Set();
        this.model.maps.forEach(m => { if (m.from === m.to) ids.add(m.from.id); });
        if (this.orbits) this.orbits.items.forEach(it => ids.add(it.map.from.id));
        return ids;
    }

    /** The curve of a routed map: shown unless the map is hidden (and not revealed). */
    _curveShown(layer) {
        return layer.map.def.hidden !== true || this.isVisible(layer);
    }

    /** Maps drawn as a curve under (row) or beside (column) the diagram: compositions and non-adjacent sets. */
    _routed(map) {
        if (!map) return false;
        if (map.def.route === 'below' || map.def.route === 'side') return true;
        if (map.def.route === 'direct' || map.from === map.to) return false;
        return map.kind === 'compose' || Math.abs(map.from.index - map.to.index) > 1;
    }

    // =========================================================================
    // LIFECYCLE
    // =========================================================================

    destroy() {
        this._destroyed = true;
        if (this.resizeObserver) this.resizeObserver.disconnect();
        if (this.sliders) this.sliders.destroy();
        if (this.interaction) this.interaction.destroy();
        if (this.linked) this.linked.destroy();
        if (this.syncGroup) this.syncGroup.leave(this);
        this._listeners.forEach(([t, type, fn, opts]) => t.removeEventListener(type, fn, opts));
        this._listeners = [];
        this.container.innerHTML = '';
    }


}

Object.assign(MatephisSets.prototype, WarningsMixin);

export default MatephisSets;
